import '@kerfjs/ui/layout.css';
import '@kerfjs/ui/sidebar.css';
import '@kerfjs/ui/webawesome.css';
import '@awesome.me/webawesome/dist/components/dialog/dialog.js';
import { DialogHeader } from '@kerfjs/ui/dialog-header';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { ValueTable } from '@kerfjs/ui/value-table';
import { delegate } from './events';
import './details.css';

type RecordDetails = { id: string; title: string; owner: string; status: string; updated: string };
type DialogElement = HTMLElement & { open: boolean };
export function createDetails(root: HTMLElement, paint: (html: ReturnType<typeof DialogHeader>) => void, records: RecordDetails[], perform: (action: 'open' | 'archive', id: string) => void) {
  let selected = records[0]?.id;
  let open = false;
  let invoker: HTMLElement | null = null;
  const render = () => {
    const item = records.find(record => record.id === selected);
    return <section class="app-root kui-layout">
      <button class="app-button" type="button" data-action="details-show">Show project details</button>
      <wa-dialog class="details-dialog" label="Project details" aria-labelledby="details-title" aria-describedby="details-summary" without-header open={open}>
        <DialogHeader title="Project details" titleId="details-title" summary="Select a project to compare its delivery status." summaryId="details-summary" actions={<button class="app-button" type="button" data-action="details-close">Close</button>} />
        <div class="details-body kui-dialog-body">
          <nav class="kui-sidebar" aria-label="Projects"><MenuHeader label="Projects" />{records.map(record => <MenuItem action="details-select" itemId={record.id} label={record.title} selected={selected === record.id} multiline />)}</nav>
          <section class="kui-section-stack" aria-live="polite">{item ? <><h2>{item.title}</h2><ValueTable label="Project metadata"><div><dt>Owner</dt><dd>{item.owner}</dd></div><div><dt>Status</dt><dd>{item.status}</dd></div><div><dt>Updated</dt><dd>{item.updated}</dd></div></ValueTable><div class="kui-control-cluster"><button class="app-button" type="button" data-action="details-archive">Archive project</button><button class="app-button" data-primary="true" type="button" data-action="details-open">Open project</button></div></> : <p>No projects available.</p>}</section>
        </div>
      </wa-dialog>
    </section>;
  };
  const getDialog = () => root.querySelector<DialogElement>('wa-dialog')!;
  const off = delegate(root, 'click', '[data-action]', element => {
    const action = element.dataset.action;
    if (action === 'details-show') { invoker = element; element.focus(); open = true; getDialog().open = true; }
    else if (action === 'details-close') getDialog().open = false;
    else if (action === 'details-select' && records.some(record => record.id === element.dataset.itemId)) { selected = element.dataset.itemId; paint(render()); }
    else if (selected && action === 'details-open') perform('open', selected);
    else if (selected && action === 'details-archive') perform('archive', selected);
  });
  const afterHide = (event: Event) => {
    if (event.target !== getDialog()) return;
    open = false;
    if (invoker?.isConnected) invoker.focus();
    else root.querySelector<HTMLElement>('[data-action="details-show"]')?.focus();
  };
  root.addEventListener('wa-after-hide', afterHide);
  paint(render());
  // Web Awesome owns focus trapping, Escape, backdrop dismissal, and the sole modal scroll boundary.
  return { render, dispose() { off(); root.removeEventListener('wa-after-hide', afterHide); } };
}

