// Application-owned stable-root event delegation. Dispose when the view unmounts.
export function delegate(root: HTMLElement, type: string, selector: string, handle: (element: HTMLElement, event: Event) => void) {
  const listener = (event: Event) => {
    const element = event.composedPath().find(node => node instanceof HTMLElement && node.matches(selector)) as HTMLElement | undefined;
    if (element && root.contains(element) && !element.matches(':disabled,[aria-disabled="true"]')) handle(element, event);
  };
  root.addEventListener(type, listener);
  return () => root.removeEventListener(type, listener);
}

