.app-button[data-primary] { color: var(--kui-color-brand-on-normal); background: var(--kui-color-brand-fill-normal); border-color: var(--kui-color-brand-border-normal); }
.app-root { min-inline-size: 0; color: var(--kui-color-text); background: var(--kui-color-surface); }
@media (prefers-reduced-motion: reduce) { .app-root { scroll-behavior: auto; } }

.details-dialog { --spacing: 0; --width: min(62rem, calc(100vw - 2rem)); }
